define(['core/log','mod_videotrack/core/confirm'],function(e,o){'use strict'
var r=function(r,c,t){o.attachToForms(r,{message:c,okString:{key:'yes',component:'moodle'},fallbackLabels:{confirm:(t=t||{}).confirm,ok:t.yes,cancel:t.cancel},logger:e,logPrefix:'mod_videotrack/report'})}
return{init:function(o){r('.videotrack-reset-student-form',(o=o||{}).confirmreset,o.labels),r('.videotrack-recalculate-form',o.confirmrecalculate,o.labels),e.debug('mod_videotrack/report: initialised')}}})
